// Compatibility cases use the Go implementation as the behavioral contract.
#[test]
fn test_sri_streaming_matches_single_write() {
 for algo in [Algo::Sha256,Algo::Sha384,Algo::Sha512] {
  let data=b"first\x00second\nthird"; let mut one=Writer::new(Vec::new(),algo);one.write_all(data).unwrap();let expected=one.sum();
  let mut chunks=Writer::new(Vec::new(),algo);for part in data.chunks(2){chunks.write_all(part).unwrap();}chunks.write_all(b"").unwrap();assert_eq!(chunks.sum().to_string(),expected.to_string());
 }
}
